 int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{color,shade(color,.91f)});d.setCornerRadius(dp(Math.max(radius,12)));d.setStroke(dp(1),LINE);return d;}static int shade(int c,float f){return Color.rgb((int)(Color.red(c)*f),(int)(Color.green(c)*f),(int)(Color.blue(c)*f));}
