 boolean canEdit(){if(session==null||working){toast("Please wait for the current task.");return false;}if(midiTake!=null){toast("Stop MIDI recording first.");return false;}if(capture!=null){toast("Stop recording and wait for the take to finish.");return false;}return true;}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}void error(String title,String message){if(dead)return;new AlertDialog.Builder(this).setTitle(title).setMessage(message==null?"The action could not be completed.":message).setPositiveButton("OK",null).show();}
 interface Task{void run()throws Exception;}void busy(String message,Task task){if(working)return;working=true;if(!dead&&!isFinishing()&&midiForeground){progress=new AlertDialog.Builder(this).setMessage(message).setCancelable(false).create();progress.show();}jobs.execute(()->{try{task.run();}catch(Throwable e){runOnUiThread(()->error("Studio",e instanceof OutOfMemoryError?"This phone ran out of memory. Try a shorter clip.":e.getMessage()));}finally{runOnUiThread(()->{working=false;if(progress!=null){progress.dismiss();progress=null;}refresh();});}});}
 File newDir()throws IOException{File dir=new File(getFilesDir(),"sessions/"+UUID.randomUUID());if(!dir.mkdirs())throw new IOException("Cannot create project storage.");return dir;}Core.Session emptySession()throws Exception{Core.Session s=new Core.Session();s.directory=newDir().getAbsolutePath();s.tracks.add(new Core.Track("Audio 01",COLORS[0]));return s;}Core.Session demoSession()throws Exception{Core.Session s=new Core.Session();s.directory=newDir().getAbsolutePath();s.title="First Light · Audio City";s.bpm=100;File dir=new File(s.directory);Core.Track drums=new Core.Track("Afropop drums",COLORS[0]);drums.volume=.75;boolean[][] pattern=defaultDrums();drums.clips.add(AudioIO.store(dir,Core.drumPattern(100,pattern,4),"City groove",0));Core.Track keys=new Core.Track("Soft keys",COLORS[2]);keys.volume=.65;keys.fx.room=true;keys.clips.add(AudioIO.store(dir,Core.chordPattern(100,1),"F · C · B♭ · B♭",0));Core.Track bass=new Core.Track("Round bass",COLORS[1]);bass.volume=.65;int bar=(int)(Core.beat(100)*4);float[] low=new float[bar*4*2];int[] notes={29,24,22,22};for(int i=0;i<4;i++)for(int beat:new int[]{0,2}){float[] note=Core.note(notes[i],.8,2);int start=i*bar+(int)Core.beat(100)*beat;for(int k=0;k<note.length&&start*2+k<low.length;k++)low[start*2+k]+=note[k];}bass.clips.add(AudioIO.store(dir,low,"Root movement",0));Core.Track voice=new Core.Track("Lead vocal",COLORS[3]);voice.fx.comp=true;voice.fx.deess=true;voice.fx.high=2;voice.fx.room=true;voice.fx.roomMix=.1;s.tracks.add(drums);s.tracks.add(bass);s.tracks.add(keys);s.tracks.add(voice);AudioIO.save(s);return s;}
 boolean[][] defaultDrums(){boolean[][] p=new boolean[3][16];for(int i:new int[]{0,6,8,11})p[0][i]=true;p[1][4]=p[1][12]=true;for(int i=0;i<16;i+=2)p[2][i]=true;return p;}
 void bind(Core.Session s){engine.stop();session=s;selected=s.tracks.isEmpty()?null:s.tracks.get(0);clip=null;undo.clear();redo.clear();getPreferences(0).edit().putString("last",s.directory).apply();refresh();}
 SampledInstruments.Pack instrumentPack(Core.Clip midiClip)throws IOException{
  if(midiClip==null)return selectedSampleInstrument;
  if(midiClip.samplePack!=null)return midiClip.samplePack;
  String id=midiClip.instrumentPackId;if(id==null||id.isEmpty())return midiClip.notes==null?selectedSampleInstrument:null;
  if("embedded:ai-drum-pads".equals(id)) {
   midiClip.samplePack=BeatPilotDrumScreen.pack(BeatPilotDrumScreen.loadKit(this));
   return midiClip.samplePack;
  }
  if(id.startsWith("bank:")){
   if(sampleBank==null)throw new IOException("The Audio City sample bank is unavailable.");
   SampleBank.Entry entry=sampleBank.byId(id.substring(5));if(entry==null)throw new IOException("The saved sample-bank instrument is unavailable: "+id);
   midiClip.samplePack=SampledInstruments.monoPack(entry.name,sampleBank.load(entry),60,entry.source+" · "+entry.license);
   return midiClip.samplePack;
  }
  for(SampledInstruments.Info info:instrumentLibrary.list())if(info.filename.equals(id)){
   midiClip.samplePack=instrumentLibrary.load(info);return midiClip.samplePack;
  }
  throw new IOException("The saved MIDI instrument is not installed: "+id);
 }
 void prepareInstrumentPacks(Core.Session project){
  if(project==null)return;
  List<String> missing=ProjectInstruments.prepare(project,clip->instrumentPack(clip));
  try { if(AiDrumTracks.embedLegacy(project)>0)AudioIO.save(project.copy()); }
  catch(Exception issue){runOnUiThread(()->error("Recovered AI drum sounds", "The recovered kit could not be saved: "+issue.getMessage()));}
  if(!missing.isEmpty())runOnUiThread(()->error("Project instrument unavailable","The project is open, but MIDI clips using these instruments stay silent until the packs are installed again:\n\n"+android.text.TextUtils.join("\n",missing)));
 }

 void refresh(){if(dead||session==null)return;projectName.setText(session.title);tempo.setText(session.bpm+"\nBPM");loop.setSelected(engine.loop);click.setSelected(engine.click);loop.setTextColor(engine.loop?ACCENT:DIM);click.setTextColor(engine.click?ACCENT:DIM);for(int i=0;i<navigation.getChildCount();i++){Button tab=(Button)navigation.getChildAt(i);tab.setSelected(screen.equals(tab.getTag())||(screen.equals("SAMPLES")&&"INSTRUMENT".equals(tab.getTag())));tab.setTextColor(tab.isSelected()?TEXT:DIM);}content.removeAllViews();timeline=null;mixer=null;eqGraph=null;reductionMeter=null;updateInspector();updateEditKeys();if(screen.equals("ARRANGE")){timeline=new Timeline();content.addView(timeline);}else if(screen.equals("MIXER")){mixer=new Mixer();content.addView(mixer);}else if(screen.equals("FX"))showFx();else if(screen.equals("SAMPLES"))showSampleBrowser();else showInstruments();updateTransport();}
 void updateTransport(){if(session==null)return;long pos=engine.position;clock.setText(engine.countInRemaining>0?"COUNT "+CountIn.number(engine.countInTotal-engine.countInRemaining,session.bpm,engine.countInBeats)+" / "+engine.countInBeats:pro.clock(pos));play.setText(engine.playing?"Ⅱ":"▶");play.setTextColor(engine.playing?ACCENT:TEXT);boolean rec=midiTake!=null||capture!=null&&capture.running;loop.setEnabled(!working&&midiTake==null&&capture==null);record.setText(rec?"■":"●");record.setActivated(rec);play.setSelected(engine.playing);record.invalidate();long millis=pos*1000/Core.RATE;timeDetail.setText(String.format(Locale.US,"%02d:%02d.%03d  /  48 kHz",millis/60000,(millis/1000)%60,millis%1000));}
 void togglePlay(){if(!canEdit())return;if(engine.playing)engine.pause();else{if(session.end()>0&&engine.position>=session.end())engine.position=0;if(requestAudioFocus()){pro.checkBluetooth();engine.play(session);}}updateTransport();}void checkpoint(){if(session==null)return;Core.Session snapshot=session.copy();undo.addLast(snapshot);pro.history.put(snapshot,pro.label());redo.clear();while(undo.size()>50)undo.removeFirst();updateEditKeys();}void undo(){if(!canEdit())return;if(undo.isEmpty()){toast("No edit to undo.");return;}engine.pause();long pos=engine.position;redo.addLast(session.copy());Core.Session s=undo.removeLast();session=s;selected=s.tracks.isEmpty()?null:s.tracks.get(0);clip=null;engine.position=pos;refresh();save(false);}
 void save(boolean announce){if(session==null)return;try{synchronized(session){AudioIO.save(session.copy());}getPreferences(0).edit().putString("last",session.directory).apply();if(announce)toast("Project saved on this phone.");}catch(Exception e){error("Could not save project",e.getMessage());}}
 void menu(){if(!canEdit())return;String[] options={"Save project","Open project","New empty project","Load demo as new project","Export (WAV, FLAC, AAC, stems)…","Undo last clip edit","Rename project","Track settings","Help & build status","Back up project (.acstudio)","Restore project backup","Redo last edit","Sample licences & credits","MIDI controller input","Export MIDI performance (.mid)","Pro tools…","Repair clip spacing & lengths"};new AlertDialog.Builder(this).setTitle("Audio City Studio").setItems(options,(d,i)->{switch(i){case 0:save(true);break;case 1:openProject();break;case 2:engine.stop();save(false);busy("Creating project…",()->{Core.Session s=emptySession();AudioIO.save(s);runOnUiThread(()->bind(s));});break;case 3:engine.stop();save(false);busy("Building demo…",()->{Core.Session s=demoSession();runOnUiThread(()->bind(s));});break;case 4:export();break;case 5:undo();break;case 6:renameProject();break;case 7:trackSettings();break;case 8:help();break;case 9:backup();break;case 10:restore();break;case 11:redoEdit();break;case 12:sampleCredits();break;case 13:midiDialog();break;case 14:exportMidi();break;case 15:pro.menu();break;case 16:repairPatternSpacing();break;}}).show();}
 void repairPatternSpacing(){if(!canEdit())return;engine.pause();try{Core.Session before;int count,melodies=0;synchronized(session){before=session.copy();count=PatternArrangement.repairOverlaps(session);for(Core.Track track:session.tracks)for(Core.Clip item:track.clips)if(ProMidi.trimRecordedEmptyEnd(session,item))melodies++;}if(count==0&&melodies==0){toast("No overlapping pattern copies or empty recorded melody ends found.");return;}undo.addLast(before);pro.history.put(before,"Repair clip spacing and lengths");while(undo.size()>50)undo.removeFirst();redo.clear();save(false);refresh();toast(count+" pattern clips re-spaced; "+melodies+" recorded clips shortened to their last note's bar. Undo is available.");}catch(Exception error){error("Clip spacing and lengths",error.getMessage());}}

 void renameProject(){if(!canEdit())return;input("Project name",session.title,false,value->{if(!value.trim().isEmpty()){session.title=value.trim().substring(0,Math.min(60,value.trim().length()));save(false);refresh();}});}interface TextAction{void run(String s);}void input(String title,String initial,boolean numeric,TextAction done){EditText field=new EditText(this);field.setText(initial);field.setSingleLine(true);if(numeric)field.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);field.setSelectAllOnFocus(true);LinearLayout wrap=column();wrap.setPadding(dp(20),dp(8),dp(20),0);wrap.addView(field);new AlertDialog.Builder(this).setTitle(title).setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{try{done.run(field.getText().toString());}catch(Exception e){error("Invalid value",e.getMessage());}}).show();}
 void tempoDialog(){if(!canEdit())return;LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText value=numberField(box,"NEW PROJECT TEMPO / 40–240 BPM",String.valueOf(session.bpm));RadioGroup mode=new RadioGroup(this);for(String label:new String[]{"Time-stretch all audio · keep pitch","Resample all audio · pitch changes","Grid only · leave audio unchanged"}){RadioButton button=new RadioButton(this);button.setText(label);button.setTextSize(12);button.setId(View.generateViewId());mode.addView(button);}mode.check(mode.getChildAt(0).getId());box.addView(mode);box.addView(label("Time stretch retimes source audio and region positions. Large changes can cause artifacts; pitch-preserving changes support 0.5×–2× per step.",11,DIM,false));new AlertDialog.Builder(this).setTitle("Change project tempo").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply tempo",(d,w)->{try{int bpm=Integer.parseInt(value.getText().toString());if(bpm<40||bpm>240)throw new NumberFormatException();if(bpm==session.bpm)return;int option=mode.indexOfChild(mode.findViewById(mode.getCheckedRadioButtonId()));engine.pause();checkpoint();if(option==2){session.bpm=bpm;save(false);refresh();return;}Core.Session original=session.copy();long cursor=engine.position;int selectedIndex=session.tracks.indexOf(selected);busy("Retiming project audio…",()->{Core.Session updated=AudioIO.retimeProject(original,bpm,option==0);runOnUiThread(()->{session=updated;selected=selectedIndex>=0&&selectedIndex<updated.tracks.size()?updated.tracks.get(selectedIndex):null;clip=null;engine.position=Math.round(cursor*original.bpm/(double)bpm);save(false);refresh();toast("Project audio and clip positions retimed to "+bpm+" BPM.");});});}catch(NumberFormatException e){toast("Use an integer tempo between 40 and 240 BPM.");}}).show();}
