 void preview(float[] samples){if(!requestAudioFocus())return;audition.stop();audition.position=0;Core.Session s=new Core.Session();Core.Track t=new Core.Track("Preview",COLORS[0]);t.clips.add(new Core.Clip("Preview",new Core.Memory(samples),"",0));s.tracks.add(t);audition.play(s);}
