 interface NoteAction{void play(int note);}class Keyboard extends View {final Paint p=new Paint(3);NoteAction action;int note=-1;int[] whites={60,62,64,65,67,69,71,72},blackNotes={61,63,66,68,70};float[] blackPos={1,2,4,5,6};Keyboard(NoteAction a){super(MainActivity.this);action=a;setContentDescription("One-octave keyboard. Register is set by the octave selector.");}protected void onDraw(Canvas c){float w=getWidth()/8f,h=getHeight()-dp(10);for(int i=0;i<8;i++){p.setColor(note==whites[i]?0xffc0d6b2:0xffd6dadd);c.drawRoundRect(i*w+1,dp(5),(i+1)*w-2,h,dp(5),dp(5),p);p.setColor(0xff68737c);p.setTextSize(dp(10));c.drawText(new String[]{"C","D","E","F","G","A","B","C"}[i],i*w+w*.4f,h-dp(10),p);}for(int i=0;i<5;i++){p.setColor(note==blackNotes[i]?0xff789b62:0xff252c31);c.drawRoundRect(blackPos[i]*w-w*.3f,dp(5),blackPos[i]*w+w*.3f,h*.62f,dp(4),dp(4),p);}}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0){float w=getWidth()/8f;note=whites[Math.max(0,Math.min(7,(int)(e.getX()/w)))];if(e.getY()<getHeight()*.6)for(int i=0;i<5;i++)if(Math.abs(e.getX()-blackPos[i]*w)<w*.3)note=blackNotes[i];invalidate();action.play(note);return true;}if(e.getAction()==1||e.getAction()==3){note=-1;invalidate();}return true;}}
