 tuneDialog[0]=new AlertDialog.Builder(this).setTitle("Vocal Tune").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Tune selected vocal",(d,w)->{engine.pause();PitchCorrector.Config config=new PitchCorrector.Config();config.key=key.getSelectedItemPosition();config.scale=scale.getSelectedItemPosition();config.strength=strength.getProgress()/100.0;config.retuneMs=new int[]{0,20,80,180}[speed.getSelectedItemPosition()];int voice=range.getSelectedItemPosition();config.minHz=voice==2?120:65;config.maxHz=voice==1?400:1000;checkpoint();session.tuneKey=config.key;session.tuneScale=config.scale;session.tuneSpeed=speed.getSelectedItemPosition();session.tuneRange=voice;session.tuneStrength=config.strength;session.tuneConfigured=true;save(false);Core.Clip processed=target.copy();final Core.Track track=selected;busy("Tracking notes and tuning the vocal…",()->{PitchCorrector.Report report=AudioIO.correctClip(processed,new File(session.directory),config);runOnUiThread(()->{int index=track.clips.indexOf(target);if(index>=0){track.clips.set(index,processed);clip=processed;}save(false);refresh();toast("Vocal tuned · "+Math.round(report.meanCorrection*100)+" cents average adjustment · "+Math.round(report.analysed==0?0:report.voiced*100.0/report.analysed)+"% voiced. Play to hear it; Undo restores the original.");});});}).create();tuneDialog[0].show();
